import{_ as a,o,c as r,a0 as t}from"./chunks/framework.Bb-2yHh0.js";const p=JSON.parse('{"title":"前言与致谢","description":"","frontmatter":{"title":"前言与致谢","outline":[2,3]},"headers":[],"relativePath":"preface.md","filePath":"preface.md"}'),i={name:"preface.md"};function n(s,e,l,c,d,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="前言与致谢" tabindex="-1">前言与致谢 <a class="header-anchor" href="#前言与致谢" aria-label="Permalink to &quot;前言与致谢&quot;">​</a></h1><h2 id="foreword" tabindex="-1">前言 <a class="header-anchor" href="#foreword" aria-label="Permalink to &quot;前言 {#foreword}&quot;">​</a></h2><p>这是一份为操作系统课程准备的草稿文本。它通过研究一个名为 xv6 的示例内核来解释操作系统的主要概念。xv6 是对 Dennis Ritchie 和 Ken Thompson 的 Unix 第六版（v6）的重新实现。xv6 松散地遵循 v6 的结构和风格，但用 ANSI C 为基于 x86 的多处理器实现。</p><p>阅读本文时应同时阅读 xv6 的源代码。这种方法受到 John Lions 的《Commentary on UNIX 6th Edition》（Peer to Peer Communications；ISBN: 1-57398-013-7；第 1 版（2000 年 6 月 14 日））的启发。关于 v6 和 xv6 的在线资源（包括若干使用 xv6 的动手作业），见 <a href="https://pdos.csail.mit.edu/6.828%E3%80%82" target="_blank" rel="noreferrer">https://pdos.csail.mit.edu/6.828。</a></p><h2 id="acknowledgements" tabindex="-1">致谢 <a class="header-anchor" href="#acknowledgements" aria-label="Permalink to &quot;致谢 {#acknowledgements}&quot;">​</a></h2><p>我们已在 MIT 的操作系统课程 6.828 中使用本文。我们感谢 6.828 的教师、助教和学生，他们直接或间接地为 xv6 做出了贡献。我们尤其要感谢 Austin Clements 和 Nickolai Zeldovich。最后，我们要感谢通过电子邮件向我们报告文中错误或提出改进建议的人们：Abutalib Aghayev、Sebastian Boehm、Anton Burtsev、Raphael Carvalho、Rasit Eskicioglu、Color Fuzzy、Giuseppe、Tao Guo、Robert Hilderman、Wolfgang Keller、Austin Liew、Pavan Maddamsetti、Jacek Masiulaniec、Michael McConville、miguelgvieira、Mark Morrissey、Harry Pan、Askar Safin、Salman Shah、Ruslan Savchenko、Pawel Szczurko、Warren Toomey、tyfkda 和 Zou Chang Wei。</p><p>如果你发现错误或有改进建议，请发送电子邮件给 Frans Kaashoek 和 Robert Morris（kaashoek,rtm@csail.mit.edu）。</p>',7)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
